1#RS:/**
2#RQ: * 3D PCB Board Renderer
3#SZ: *
4#JR: * Renders the PCB board as a 3D scene with Three.js.
5#PP: * Coordinate system: X/Y from board data (mm), Z is stack-up axis (Z-up).
6#KH: * Board bottom face at Z=0, top face at Z=1.6mm.
7#NB: *
8#KR: * Copper layers:
9#TV: *   Bottom copper: Z = 0.035 mm (copper thickness above board bottom)
10#SV: *   Top copper:    Z = 1.565 mm (board thickness minus copper thickness)
11#TY: *   Pads get slight Z-offset above traces to prevent Z-fighting.
12#YQ: */
13#BQ:
14#MV:import * as THREE from 'three';
15#QZ:import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';
16#SV:import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
17#ZZ:import type { BoardSnapshot, TraceInfo, ViaInfo, ComponentInfo } from './types';
18#RN:import { LAYER_COLORS, LAYER_MASK, type LayerVisibility } from './layers';
19#YT:
20#WP:/** Component body height for SMD parts in mm */
21#MN:const SMD_HEIGHT_MM = 1.2;
22#ZP:
23#HZ:/** Component body height for THT parts in mm */
24#PP:const THT_HEIGHT_MM = 5.0;
25#XW:
26#XM:/** Standard PCB thickness in mm */
27#KY:const BOARD_THICKNESS_MM = 1.6;
28#HQ:
29#ZH:/** Copper layer thickness in mm */
30#KK:const COPPER_THICKNESS_MM = 0.035;
31#SZ:
32#VT:/** Z-heights for copper layers (center of copper slab) */
33#PQ:const Z_BOTTOM_COPPER = COPPER_THICKNESS_MM; // 0.035 mm
34#YQ:const Z_TOP_COPPER = BOARD_THICKNESS_MM - COPPER_THICKNESS_MM; // 1.565 mm
35#TX:
36#YV:/** Pad Z-offsets slightly above traces to avoid Z-fighting */
37#RW:const Z_BOTTOM_PAD = Z_BOTTOM_COPPER + 0.005; // 0.04 mm
38#TW:const Z_TOP_PAD = Z_TOP_COPPER + 0.005; // 1.57 mm
39#MS:
40#VS:/** Nanometers to millimeters conversion factor */
41#KM:const NM_TO_MM = 1e-6;
42#XN:
43#VQ:/** PCB substrate green material color */
44#YS:const PCB_GREEN = 0x1a7a3a;
45#KT:
46#WM:/** PCB substrate roughness for physical material */
47#ZR:const PCB_ROUGHNESS = 0.7;
48#BY:
49#HW:/** Parse a CSS hex color string to a Three.js Color */
50#BS:function hexToColor(hex: string): THREE.Color {
51#VZ:  return new THREE.Color(hex);
52#SJ:}
53#NB:
54#SY:/**
55#JW: * Create a merged copper mesh from a flat positions array and add it to a group.
56#WJ: * Used for both traces and pads on each layer to avoid duplicating the
57#JS: * BufferGeometry + MeshStandardMaterial construction.
58#RX: */
59#QJ:function addCopperMesh(
60#XP:  positions: number[],
61#MT:  colorHex: string,
62#QK:  name: string,
63#XK:  group: THREE.Group,
64#XJ:): void {
65#KK:  if (positions.length === 0) return;
66#NS:  const geo = new THREE.BufferGeometry();
67#NM:  geo.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
68#MY:  geo.computeVertexNormals();
69#RH:  const mat = new THREE.MeshStandardMaterial({
70#NN:    color: hexToColor(colorHex),
71#RN:    metalness: 0.6,
72#MQ:    roughness: 0.3,
73#PK:    side: THREE.DoubleSide,
74#XB:  });
75#VY:  const mesh = new THREE.Mesh(geo, mat);
76#YZ:  mesh.name = name;
77#ZS:  group.add(mesh);
78#SK:}
79#BR:
80#ZS:export class Renderer3D {
81#ZZ:  private renderer: THREE.WebGLRenderer | null = null;
82#HH:  private scene: THREE.Scene | null = null;
83#WZ:  private camera: THREE.PerspectiveCamera | null = null;
84#RW:  private controls: OrbitControls | null = null;
85#VY:  private container: HTMLElement | null = null;
86#MX:  private animFrameId: number | null = null;
87#QT:  private active = false;
88#HM:  private boardGroup: THREE.Group | null = null;
89#WY:
90#TR:  /** Named layer groups for visibility toggling */
91#QW:  private layerGroups: Map<string, THREE.Group> = new Map();
92#JZ:
93#TS:  /** FPS tracking */
94#VS:  private lastFrameTime = 0;
95#KB:  private frameCount = 0;
96#HR:  private currentFps = 0;
97#HT:  private fpsLogTimer = 0;
98#BP:
99#JX:  /** Geometry counts for debug surface */
100#NY:  private _componentCount = 0;
101#TJ:  private _traceSegmentCount = 0;
102#YK:  private _padCount = 0;
103#KM:  private _viaCount = 0;
104#NJ:
105#NV:  /** Loaded GLTF models: refdes → Group */
106#XP:  private loadedModels: Map<string, THREE.Group> = new Map();
107#TS:
108#MW:  /**
109#JH:   * Initialize the 3D renderer inside the given container element.
110#RW:   * Creates WebGL renderer, scene, camera, controls, and lighting.
111#MX:   */
112#WB:  init(container: HTMLElement): void {
113#YT:    this.container = container;
114#BJ:
115#HW:    // Create WebGL renderer
116#VN:    try {
117#KK:      this.renderer = new THREE.WebGLRenderer({
118#SR:        antialias: true,
119#KP:        alpha: false,
120#KS:      });
121#MQ:    } catch (e) {
122#RX:      console.error('[3D] WebGL not available', e);
123#QV:      throw new Error('WebGL not available');
124#JT:    }
125#YB:
126#RT:    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
127#NN:    this.renderer.setSize(container.clientWidth, container.clientHeight);
128#QQ:    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
129#RN:    this.renderer.toneMappingExposure = 1.0;
130#SH:    this.renderer.domElement.style.position = 'absolute';
131#NH:    this.renderer.domElement.style.top = '0';
132#VS:    this.renderer.domElement.style.left = '0';
133#MV:    this.renderer.domElement.id = 'three-canvas';
134#QJ:    container.appendChild(this.renderer.domElement);
135#QX:
136#PX:    // Scene
137#PS:    this.scene = new THREE.Scene();
138#SK:    this.setBackgroundFromCSS();
139#QR:
140#TK:    // Camera — perspective, looking down at board
141#SQ:    const aspect = container.clientWidth / container.clientHeight;
142#SY:    this.camera = new THREE.PerspectiveCamera(45, aspect, 0.1, 10000);
143#JW:    this.camera.position.set(0, 0, 100);
144#ZZ:    this.camera.up.set(0, 1, 0);
145#VM:
146#YR:    // OrbitControls
147#KS:    this.controls = new OrbitControls(this.camera, this.renderer.domElement);
148#RZ:    this.controls.enableDamping = true;
149#XN:    this.controls.dampingFactor = 0.1;
150#BP:    this.controls.target.set(0, 0, 0);
151#XW:    this.controls.update();
152#HM:
153#BT:    // Lighting — ambient + directional for even illumination
154#NJ:    const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
155#SJ:    this.scene.add(ambientLight);
156#TT:
157#TY:    const dirLight1 = new THREE.DirectionalLight(0xffffff, 0.8);
158#YR:    dirLight1.position.set(50, 80, 100);
159#JZ:    this.scene.add(dirLight1);
160#ZB:
161#NH:    const dirLight2 = new THREE.DirectionalLight(0xffffff, 0.3);
162#QV:    dirLight2.position.set(-30, -50, 60);
163#XY:    this.scene.add(dirLight2);
164#SK:
165#TV:    // Board group for easy clearing
166#BR:    this.boardGroup = new THREE.Group();
167#BW:    this.scene.add(this.boardGroup);
168#BT:
169#MH:    // Resize handler
170#TQ:    this.onResize = this.onResize.bind(this);
171#NV:    window.addEventListener('resize', this.onResize);
172#VK:
173#ZQ:    // Start animation loop
174#MM:    this.active = true;
175#TJ:    this.animate();
176#QN:
177#WX:    // Expose debug surface
178#ZP:    this.updateDebugSurface();
179#JZ:
180#TX:    console.log('[3D] Initialized');
181#RK:  }
182#NT:
183#JV:  /**
184#RW:   * Update board geometry from a BoardSnapshot.
185#YT:   * Builds: substrate slab, copper traces, pads, vias, with layer groups for visibility.
186#QV:   */
187#BM:  updateBoard(snapshot: BoardSnapshot, layers: LayerVisibility): void {
188#SH:    if (!this.boardGroup || !this.scene) return;
189#RS:
190#MN:    // Clear existing board geometry and layer groups
191#JH:    this.clearBoardGroup();
192#WT:    this.layerGroups.clear();
193#XN:
194#JV:    if (!snapshot.board) {
195#PK:      console.log('[3D] No board data');
196#BX:      this.updateDebugSurface();
197#NZ:      return;
198#WQ:    }
199#BN:
200#SQ:    const widthMm = snapshot.board.width_nm * NM_TO_MM;
201#WN:    const heightMm = snapshot.board.height_nm * NM_TO_MM;
202#JM:
203#PV:    // Board substrate — box geometry centered on X/Y, bottom at Z=0
204#SQ:    const subGeo = new THREE.BoxGeometry(widthMm, heightMm, BOARD_THICKNESS_MM);
205#QP:    subGeo.translate(widthMm / 2, heightMm / 2, BOARD_THICKNESS_MM / 2);
206#XQ:
207#WR:    const subMat = new THREE.MeshPhysicalMaterial({
208#JZ:      color: PCB_GREEN,
209#RN:      roughness: PCB_ROUGHNESS,
210#WS:      metalness: 0.05,
211#WP:      clearcoat: 0.3,
212#HH:      clearcoatRoughness: 0.4,
213#PY:    });
214#KZ:
215#JN:    const boardMesh = new THREE.Mesh(subGeo, subMat);
216#NY:    boardMesh.name = 'board-substrate';
217#RS:    this.boardGroup.add(boardMesh);
218#QV:
219#MP:    // Create layer groups
220#YH:    const topGroup = new THREE.Group();
221#BQ:    topGroup.name = 'layer-top';
222#XP:    const bottomGroup = new THREE.Group();
223#XK:    bottomGroup.name = 'layer-bottom';
224#NY:    const viaGroup = new THREE.Group();
225#NK:    viaGroup.name = 'layer-vias';
226#XJ:
227#YR:    this.boardGroup.add(topGroup);
228#KV:    this.boardGroup.add(bottomGroup);
229#VS:    this.boardGroup.add(viaGroup);
230#QP:
231#NR:    this.layerGroups.set('topCopper', topGroup);
232#MR:    this.layerGroups.set('bottomCopper', bottomGroup);
233#BV:    this.layerGroups.set('vias', viaGroup);
234#MY:
235#JS:    // Build copper geometry
236#HJ:    this.buildTraces(snapshot.traces || [], topGroup, bottomGroup);
237#JY:    this.buildPads(snapshot.components || [], topGroup, bottomGroup);
238#PH:    this.buildVias(snapshot.vias || [], viaGroup);
239#HS:
240#RV:    // Build component bodies (on top layer group for now — all top-side)
241#JQ:    this.buildComponents(snapshot.components || [], topGroup);
242#TK:
243#HH:    // Apply initial layer visibility
244#NJ:    this.updateLayerVisibility(layers);
245#VJ:
246#VN:    // Set orbit target to board center
247#SH:    if (this.controls && this.camera) {
248#PR:      const cx = widthMm / 2;
249#KX:      const cy = heightMm / 2;
250#JQ:      const cz = BOARD_THICKNESS_MM / 2;
251#HT:      this.controls.target.set(cx, cy, cz);
252#TZ:
253#VN:      const maxDim = Math.max(widthMm, heightMm);
254#HZ:      const distance = maxDim * 1.5;
255#KB:      this.camera.position.set(cx, cy - distance * 0.3, distance);
256#MK:      this.controls.update();
257#SV:    }
258#PY:
259#JY:    const componentCount = snapshot.components?.length ?? 0;
260#HH:    console.log(`[3D] Board updated: ${widthMm.toFixed(1)}x${heightMm.toFixed(1)} mm, ${componentCount} components`);
261#ZP:    this.updateDebugSurface();
262#JQ:  }
263#WJ:
264#HT:  /**
265#WT:   * Update visibility of layer groups based on checkbox state.
266#YV:   * Called from main.ts layer checkbox handlers.
267#ZB:   */
268#VT:  updateLayerVisibility(layers: LayerVisibility): void {
269#YZ:    const topGroup = this.layerGroups.get('topCopper');
270#ZT:    const bottomGroup = this.layerGroups.get('bottomCopper');
271#PJ:    const viaGroup = this.layerGroups.get('vias');
272#NM:
273#YK:    if (topGroup) topGroup.visible = layers.topCopper;
274#KH:    if (bottomGroup) bottomGroup.visible = layers.bottomCopper;
275#VZ:    // Vias visible when either copper layer is visible
276#MP:    if (viaGroup) viaGroup.visible = layers.topCopper || layers.bottomCopper;
277#JH:  }
278#NB:
279#WP:  /**
280#BZ:   * Dispose all Three.js resources and remove DOM elements.
281#BR:   */
282#BZ:  dispose(): void {
283#RY:    this.active = false;
284#XQ:
285#RT:    if (this.animFrameId !== null) {
286#RK:      cancelAnimationFrame(this.animFrameId);
287#VQ:      this.animFrameId = null;
288#WQ:    }
289#XR:
290#HT:    window.removeEventListener('resize', this.onResize);
291#BV:
292#BX:    // Dispose board group contents
293#JH:    this.clearBoardGroup();
294#YH:
295#NH:    // Dispose controls
296#WJ:    if (this.controls) {
297#SP:      this.controls.dispose();
298#NY:      this.controls = null;
299#JZ:    }
300#NX:
301#ZJ:    // Dispose scene children (lights, sprites, etc.)
302#WM:    if (this.scene) {
303#QB:      this.scene.traverse((obj) => {
304#KW:        if (obj instanceof THREE.Mesh) {
305#WN:          obj.geometry?.dispose();
306#PZ:          if (obj.material) {
307#KJ:            if (Array.isArray(obj.material)) {
308#PV:              obj.material.forEach(m => m.dispose());
309#YQ:            } else {
310#BP:              obj.material.dispose();
311#WK:            }
312#XM:          }
313#SP:        }
314#BX:        if (obj instanceof THREE.Sprite) {
315#MB:          const spriteMat = obj.material as THREE.SpriteMaterial;
316#QZ:          spriteMat.map?.dispose();
317#WQ:          spriteMat.dispose();
318#ZZ:        }
319#MJ:      });
320#RQ:      this.scene.clear();
321#JY:      this.scene = null;
322#JK:    }
323#HY:
324#TS:    // Remove renderer DOM element
325#YT:    if (this.renderer) {
326#JJ:      if (this.renderer.domElement.parentElement) {
327#YS:        this.renderer.domElement.parentElement.removeChild(this.renderer.domElement);
328#XX:      }
329#BX:      this.renderer.dispose();
330#RQ:      this.renderer = null;
331#BM:    }
332#YP:
333#BT:    this.camera = null;
334#JM:    this.boardGroup = null;
335#ZZ:    this.container = null;
336#WT:    this.layerGroups.clear();
337#XW:
338#RJ:    // Update debug surface
339#ZP:    this.updateDebugSurface();
340#TP:
341#WK:    console.log('[3D] Disposed');
342#XY:  }
343#QB:
344#RV:  /**
345#JH:   * Update the scene background color from a CSS color string.
346#BM:   */
347#XV:  setBackground(color: string): void {
348#WM:    if (this.scene) {
349#KJ:      this.scene.background = new THREE.Color(color);
350#WM:    }
351#BP:  }
352#NX:
353#JV:  /**
354#KS:   * Whether the renderer is currently active and running.
355#PP:   */
356#TN:  get isActive(): boolean {
357#KX:    return this.active;
358#RJ:  }
359#QR:
360#QP:  /**
361#QS:   * Load a GLB 3D model for a component, replacing its placeholder box mesh.
362#YH:   * Finds the placeholder by name `component-${refdes}`, copies its transform,
363#JQ:   * removes it, and adds the loaded GLTF scene at the same position/rotation.
364#NP:   * Errors are logged to console — callers don't need to handle failures.
365#QJ:   */
366#YP:  loadComponentModel(url: string, refdes: string): void {
367#ZZ:    if (!this.boardGroup) {
368#MT:      console.error(`[3D] GLB load failed for ${refdes}: no board group`);
369#NZ:      return;
370#WN:    }
371#MZ:
372#KH:    const meshName = `component-${refdes}`;
373#MJ:    let placeholder: THREE.Object3D | null = null;
374#BX:    this.boardGroup.traverse((obj) => {
375#HH:      if (obj.name === meshName) placeholder = obj;
376#PJ:    });
377#VN:
378#ZV:    if (!placeholder) {
379#RB:      console.error(`[3D] GLB load failed for ${refdes}: placeholder mesh "${meshName}" not found`);
380#NZ:      return;
381#RM:    }
382#TB:
383#NH:    const loader = new GLTFLoader();
384#TX:    const boardGroup = this.boardGroup;
385#WR:    const loadedModels = this.loadedModels;
386#WT:    const pos = (placeholder as THREE.Mesh).position.clone();
387#VX:    const rot = (placeholder as THREE.Mesh).rotation.clone();
388#NN:
389#XR:    loader.load(
390#QX:      url,
391#ZT:      (gltf) => {
392#MQ:        const model = gltf.scene;
393#YQ:        model.position.copy(pos);
394#NT:        model.rotation.copy(rot);
395#SQ:        model.name = `model-${refdes}`;
396#XH:
397#RS:        // Remove the placeholder box
398#VZ:        if (placeholder && placeholder.parent) {
399#BZ:          if (placeholder instanceof THREE.Mesh) {
400#ZW:            placeholder.geometry?.dispose();
401#QW:            if (placeholder.material) {
402#SB:              if (Array.isArray(placeholder.material)) {
403#QW:                placeholder.material.forEach(m => m.dispose());
404#MZ:              } else {
405#SK:                (placeholder.material as THREE.Material).dispose();
406#JM:              }
407#XZ:            }
408#RT:          }
409#YQ:          placeholder.parent.remove(placeholder);
410#MW:        }
411#PN:
412#SV:        // Add loaded model to the same parent (topGroup)
413#TB:        boardGroup.traverse((obj) => {
414#MJ:          if (obj.name === 'layer-top') {
415#PP:            obj.add(model);
416#JH:          }
417#RX:        });
418#PB:
419#TN:        loadedModels.set(refdes, model);
420#WN:        console.log(`[3D] GLB loaded for ${refdes}: ${url}`);
421#JJ:      },
422#XY:      undefined,
423#JV:      (error) => {
424#XV:        console.error(`[3D] GLB load failed for ${refdes}: ${error}`);
425#NW:      },
426#RK:    );
427#RX:  }
428#PN:
429#PJ:  // -- Copper geometry builders --
430#WZ:
431#MB:  /**
432#RZ:   * Build merged trace geometry per layer.
433#VY:   * Each trace segment → flat quad (4 verts, 2 tris) at the correct Z-height.
434#KN:   * All segments on a layer are merged into one BufferGeometry for draw-call efficiency.
435#XP:   */
436#SK:  private buildTraces(traces: TraceInfo[], topGroup: THREE.Group, bottomGroup: THREE.Group): void {
437#BQ:    // Bucket segments by layer
438#QY:    const topPositions: number[] = [];
439#HJ:    const bottomPositions: number[] = [];
440#QR:
441#BW:    let topSegCount = 0;
442#MN:    let bottomSegCount = 0;
443#SB:
444#KP:    for (const trace of traces) {
445#HS:      const widthMm = trace.width * NM_TO_MM;
446#QZ:      const halfW = widthMm / 2;
447#SS:      const isTop = trace.layer === 'Top';
448#SV:      const zHeight = isTop ? Z_TOP_COPPER : Z_BOTTOM_COPPER;
449#QP:      const positions = isTop ? topPositions : bottomPositions;
450#ZT:
451#QB:      for (const seg of trace.segments) {
452#XV:        const sx = seg.start_x * NM_TO_MM;
453#MM:        const sy = seg.start_y * NM_TO_MM;
454#RX:        const ex = seg.end_x * NM_TO_MM;
455#JW:        const ey = seg.end_y * NM_TO_MM;
456#VQ:
457#NQ:        // Direction vector and perpendicular for width
458#ZR:        const dx = ex - sx;
459#HS:        const dy = ey - sy;
460#SV:        const len = Math.sqrt(dx * dx + dy * dy);
461#JJ:        if (len < 1e-6) continue; // skip zero-length segments
462#HM:
463#RS:        // Perpendicular (normalized) scaled by half-width
464#HM:        const px = (-dy / len) * halfW;
465#KB:        const py = (dx / len) * halfW;
466#JX:
467#RS:        // Quad corners: start-left, start-right, end-right, end-left
468#WZ:        const slx = sx + px, sly = sy + py;
469#BY:        const srx = sx - px, sry = sy - py;
470#RJ:        const erx = ex - px, ery = ey - py;
471#VS:        const elx = ex + px, ely = ey + py;
472#RJ:
473#ZR:        // Triangle 1: SL, SR, ER
474#WY:        positions.push(slx, sly, zHeight);
475#HZ:        positions.push(srx, sry, zHeight);
476#KT:        positions.push(erx, ery, zHeight);
477#VB:
478#VY:        // Triangle 2: SL, ER, EL
479#WY:        positions.push(slx, sly, zHeight);
480#KT:        positions.push(erx, ery, zHeight);
481#RY:        positions.push(elx, ely, zHeight);
482#YY:
483#KZ:        if (isTop) topSegCount++;
484#VM:        else bottomSegCount++;
485#MW:      }
486#QH:    }
487#QW:
488#RH:    // Create copper trace meshes per layer
489#YH:    addCopperMesh(topPositions, LAYER_COLORS.top_copper, 'traces-top', topGroup);
490#QP:    addCopperMesh(bottomPositions, LAYER_COLORS.bottom_copper, 'traces-bottom', bottomGroup);
491#VX:
492#TS:    this._traceSegmentCount = topSegCount + bottomSegCount;
493#VP:
494#JN:    if (topSegCount > 0) console.log(`[3D] Built ${topSegCount} trace segments on layer Top`);
495#RB:    else console.log('[3D] Warning: 0 traces on layer Top');
496#KH:    if (bottomSegCount > 0) console.log(`[3D] Built ${bottomSegCount} trace segments on layer Bottom`);
497#VB:    else console.log('[3D] Warning: 0 traces on layer Bottom');
498#KT:  }
499#ZN:
500#PP:  /**
501#VV:   * Build pad geometry from components.
502#WV:   * Pads are merged into per-layer BufferGeometry. Through-hole pads go in both groups.
503#NH:   */
504#RR:  private buildPads(components: ComponentInfo[], topGroup: THREE.Group, bottomGroup: THREE.Group): void {
505#QY:    const topPositions: number[] = [];
506#HJ:    const bottomPositions: number[] = [];
507#XH:    let padCount = 0;
508#RP:
509#BH:    for (const comp of components) {
510#XZ:      const compXmm = comp.x_nm * NM_TO_MM;
511#HT:      const compYmm = comp.y_nm * NM_TO_MM;
512#TS:      const radians = (comp.rotation_mdeg / 1000) * (Math.PI / 180);
513#JV:      const cosR = Math.cos(radians);
514#KS:      const sinR = Math.sin(radians);
515#YV:
516#QH:      for (const pad of comp.pads) {
517#TJ:        // Rotate pad offset by component rotation
518#JB:        const padXmm = pad.x_nm * NM_TO_MM;
519#ZN:        const padYmm = pad.y_nm * NM_TO_MM;
520#BQ:        const rotX = padXmm * cosR - padYmm * sinR;
521#NJ:        const rotY = padXmm * sinR + padYmm * cosR;
522#TH:
523#KM:        const worldX = compXmm + rotX;
524#XM:        const worldY = compYmm + rotY;
525#XW:        const wMm = pad.width_nm * NM_TO_MM;
526#YZ:        const hMm = pad.height_nm * NM_TO_MM;
527#PH:
528#ZB:        const isTop = (pad.layer_mask & LAYER_MASK.TOP_COPPER) !== 0;
529#TW:        const isBottom = (pad.layer_mask & LAYER_MASK.BOTTOM_COPPER) !== 0;
530#PW:
531#RJ:        // Build pad shape as triangles based on pad.shape
532#KB:        const padTris = this.buildPadTriangles(worldX, worldY, wMm, hMm, radians, pad.shape);
533#WY:
534#NK:        if (isTop) {
535#NH:          for (const tri of padTris) {
536#RV:            topPositions.push(tri[0], tri[1], Z_TOP_PAD);
537#JM:            topPositions.push(tri[2], tri[3], Z_TOP_PAD);
538#BY:            topPositions.push(tri[4], tri[5], Z_TOP_PAD);
539#PJ:          }
540#QH:        }
541#RQ:        if (isBottom) {
542#NH:          for (const tri of padTris) {
543#BV:            bottomPositions.push(tri[0], tri[1], Z_BOTTOM_PAD);
544#KB:            bottomPositions.push(tri[2], tri[3], Z_BOTTOM_PAD);
545#KP:            bottomPositions.push(tri[4], tri[5], Z_BOTTOM_PAD);
546#QY:          }
547#SM:        }
548#QJ:
549#NZ:        padCount++;
550#PS:      }
551#WH:    }
552#HX:
553#QK:    // Create pad meshes per layer
554#XM:    addCopperMesh(topPositions, LAYER_COLORS.top_copper, 'pads-top', topGroup);
555#RP:    addCopperMesh(bottomPositions, LAYER_COLORS.bottom_copper, 'pads-bottom', bottomGroup);
556#MR:
557#JB:    this._padCount = padCount;
558#JV:
559#TY:    console.log(`[3D] Built ${padCount} pads`);
560#TH:  }
561#BH:
562#BW:  /**
563#PQ:   * Build triangles for a single pad shape at the given world position.
564#WB:   * Returns array of [x0,y0, x1,y1, x2,y2] triangles.
565#JW:   */
566#RV:  private buildPadTriangles(
567#ZW:    cx: number, cy: number,
568#XW:    w: number, h: number,
569#NH:    rotation: number,
570#MN:    shape: string,
571#PP:  ): number[][] {
572#YV:    const cosR = Math.cos(rotation);
573#HW:    const sinR = Math.sin(rotation);
574#NP:
575#RY:    // Helper to rotate a point around (cx, cy)
576#NH:    const rot = (lx: number, ly: number): [number, number] => {
577#PM:      const rx = lx * cosR - ly * sinR;
578#TV:      const ry = lx * sinR + ly * cosR;
579#WT:      return [cx + rx, cy + ry];
580#RV:    };
581#ZM:
582#NX:    const hw = w / 2;
583#ZZ:    const hh = h / 2;
584#RR:
585#PB:    switch (shape) {
586#BN:      case 'circle': {
587#YQ:        // Approximate circle with 12-segment fan
588#KP:        const segments = 12;
589#ST:        const tris: number[][] = [];
590#TV:        const r = Math.max(hw, hh);
591#ZK:        for (let i = 0; i < segments; i++) {
592#VS:          const a0 = (i / segments) * Math.PI * 2;
593#XB:          const a1 = ((i + 1) / segments) * Math.PI * 2;
594#NW:          const [x0, y0] = rot(Math.cos(a0) * r, Math.sin(a0) * r);
595#MM:          const [x1, y1] = rot(Math.cos(a1) * r, Math.sin(a1) * r);
596#YH:          tris.push([cx, cy, x0, y0, x1, y1]);
597#BX:        }
598#YX:        return tris;
599#WZ:      }
600#MP:
601#KP:      case 'roundrect':
602#RM:      case 'oblong': {
603#BM:        // Approximate with 4 corner arcs (4 segments each) + rect body
604#PP:        // For simplicity and merge-efficiency, use an octagon approximation
605#SN:        const cornerR = Math.min(hw, hh) * 0.25;
606#ST:        const tris: number[][] = [];
607#PK:
608#NT:        // 8 corners of the octagon
609#XJ:        const pts: [number, number][] = [
610#SB:          rot(-hw + cornerR, -hh),
611#HB:          rot(hw - cornerR, -hh),
612#XQ:          rot(hw, -hh + cornerR),
613#WB:          rot(hw, hh - cornerR),
614#VZ:          rot(hw - cornerR, hh),
615#VW:          rot(-hw + cornerR, hh),
616#ZW:          rot(-hw, hh - cornerR),
617#WB:          rot(-hw, -hh + cornerR),
618#PM:        ];
619#XV:
620#MY:        // Fan triangulation from center
621#PY:        for (let i = 0; i < pts.length; i++) {
622#MX:          const [x0, y0] = pts[i];
623#YR:          const [x1, y1] = pts[(i + 1) % pts.length];
624#YH:          tris.push([cx, cy, x0, y0, x1, y1]);
625#ZK:        }
626#YX:        return tris;
627#VR:      }
628#YP:
629#TT:      case 'rect':
630#XY:      default: {
631#PT:        // Two triangles for a rectangle
632#BW:        const [tl0, tl1] = rot(-hw, -hh);
633#QM:        const [tr0, tr1] = rot(hw, -hh);
634#MZ:        const [br0, br1] = rot(hw, hh);
635#RJ:        const [bl0, bl1] = rot(-hw, hh);
636#MP:        return [
637#RK:          [tl0, tl1, tr0, tr1, br0, br1],
638#XV:          [tl0, tl1, br0, br1, bl0, bl1],
639#MH:        ];
640#SQ:      }
641#TK:    }
642#XS:  }
643#SX:
644#YX:  /**
645#ZR:   * Build via geometry using InstancedMesh for efficiency.
646#TT:   * Vias are cylinders spanning full board thickness with a tube geometry (drilled hole).
647#BQ:   */
648#WY:  private buildVias(vias: ViaInfo[], viaGroup: THREE.Group): void {
649#BP:    if (vias.length === 0) {
650#HJ:      console.log('[3D] Built 0 vias (instanced)');
651#NZ:      return;
652#MT:    }
653#VB:
654#YW:    // Use tube geometry (cylinder with inner hole) for via annular ring
655#SP:    // Template: outer_diameter, board thickness height, 16 radial segments
656#MS:    const firstVia = vias[0];
657#HM:    const outerR = (firstVia.outer_diameter * NM_TO_MM) / 2;
658#BX:    const innerR = (firstVia.drill * NM_TO_MM) / 2;
659#RQ:
660#SY:    // For vias with varying sizes, use the most common size as template
661#YS:    // For simplicity, use a single tube geometry and per-instance scale
662#QN:    const tubeGeo = new THREE.CylinderGeometry(outerR, outerR, BOARD_THICKNESS_MM, 16, 1, false);
663#XB:    // CylinderGeometry is Y-up by default; rotate to Z-up
664#JK:    tubeGeo.rotateX(Math.PI / 2);
665#HY:
666#TV:    const viaMat = new THREE.MeshStandardMaterial({
667#ZS:      color: hexToColor(LAYER_COLORS.via),
668#SM:      metalness: 0.7,
669#XS:      roughness: 0.3,
670#RZ:    });
671#RZ:
672#KB:    const instancedMesh = new THREE.InstancedMesh(tubeGeo, viaMat, vias.length);
673#HB:    instancedMesh.name = 'vias';
674#PB:
675#XV:    const drillGeo = new THREE.CylinderGeometry(innerR, innerR, BOARD_THICKNESS_MM + 0.02, 16, 1, false);
676#QN:    drillGeo.rotateX(Math.PI / 2);
677#XB:
678#ZH:    const drillMat = new THREE.MeshStandardMaterial({
679#JZ:      color: PCB_GREEN,
680#RN:      roughness: PCB_ROUGHNESS,
681#PM:    });
682#ZK:
683#NK:    const drillInstancedMesh = new THREE.InstancedMesh(drillGeo, drillMat, vias.length);
684#RW:    drillInstancedMesh.name = 'via-drills';
685#BJ:
686#RH:    const matrix = new THREE.Matrix4();
687#TT:    const refOuterR = outerR;
688#QV:    const refInnerR = innerR;
689#KN:
690#BR:    for (let i = 0; i < vias.length; i++) {
691#NX:      const via = vias[i];
692#XK:      const x = via.x * NM_TO_MM;
693#NX:      const y = via.y * NM_TO_MM;
694#NK:      const z = BOARD_THICKNESS_MM / 2; // center of board
695#ZV:
696#KR:      // Scale factor relative to reference via
697#BP:      const thisOuterR = (via.outer_diameter * NM_TO_MM) / 2;
698#HR:      const thisInnerR = (via.drill * NM_TO_MM) / 2;
699#QZ:      const outerScale = refOuterR > 0 ? thisOuterR / refOuterR : 1;
700#VV:      const innerScale = refInnerR > 0 ? thisInnerR / refInnerR : 1;
701#XW:
702#BJ:      // Outer annular ring
703#WV:      matrix.makeScale(outerScale, outerScale, 1);
704#ZV:      matrix.setPosition(x, y, z);
705#JP:      instancedMesh.setMatrixAt(i, matrix);
706#QB:
707#PX:      // Drill hole (slightly taller to punch through)
708#XH:      matrix.makeScale(innerScale, innerScale, 1);
709#ZV:      matrix.setPosition(x, y, z);
710#ZX:      drillInstancedMesh.setMatrixAt(i, matrix);
711#KV:    }
712#VV:
713#PQ:    instancedMesh.instanceMatrix.needsUpdate = true;
714#KP:    drillInstancedMesh.instanceMatrix.needsUpdate = true;
715#MB:
716#QS:    viaGroup.add(instancedMesh);
717#TH:    viaGroup.add(drillInstancedMesh);
718#NB:
719#WN:    this._viaCount = vias.length;
720#RT:
721#JW:    console.log(`[3D] Built ${vias.length} vias (instanced)`);
722#ZX:  }
723#QB:
724#HZ:  /**
725#BY:   * Build component body geometry as colored boxes with refdes labels.
726#TH:   * SMD parts get 1.2mm height, THT parts get 5mm height.
727#QW:   * IC packages (U/IC prefix) are dark gray, passives (R/C/L) are tan.
728#XV:   */
729#XS:  private buildComponents(components: ComponentInfo[], topGroup: THREE.Group): void {
730#YS:    let smdCount = 0;
731#TR:    let thtCount = 0;
732#NJ:
733#BM:    const icMat = new THREE.MeshStandardMaterial({
734#RB:      color: 0x404040,
735#YM:      metalness: 0.3,
736#VY:      roughness: 0.5,
737#RJ:    });
738#VT:
739#MT:    const passiveMat = new THREE.MeshStandardMaterial({
740#YS:      color: 0xc2a366,
741#QK:      metalness: 0.1,
742#BZ:      roughness: 0.6,
743#WB:    });
744#YR:
745#BH:    for (const comp of components) {
746#JV:      let bodyW = comp.body_width_nm * NM_TO_MM;
747#PZ:      let bodyH = comp.body_height_nm * NM_TO_MM;
748#WB:
749#RY:      // Fallback: compute bounding box from pads if body dimensions missing
750#JR:      // NaN-safe: !(x > 0) catches NaN, undefined, 0, and negative
751#VJ:      if (!(bodyW > 0) || !(bodyH > 0)) {
752#ZK:        if (comp.pads.length > 0) {
753#TZ:          let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
754#JS:          for (const pad of comp.pads) {
755#ZH:            const hw = (pad.width_nm * NM_TO_MM) / 2;
756#XH:            const hh = (pad.height_nm * NM_TO_MM) / 2;
757#XK:            const px = pad.x_nm * NM_TO_MM;
758#BM:            const py = pad.y_nm * NM_TO_MM;
759#TN:            minX = Math.min(minX, px - hw);
760#RB:            minY = Math.min(minY, py - hh);
761#WW:            maxX = Math.max(maxX, px + hw);
762#MP:            maxY = Math.max(maxY, py + hh);
763#ZJ:          }
764#JJ:          bodyW = maxX - minX;
765#YY:          bodyH = maxY - minY;
766#SP:          console.log(`[3D] Warning: component ${comp.refdes} has no body dimensions, using pad bbox fallback`);
767#RQ:        } else {
768#MJ:          continue; // No body info at all — skip
769#QR:        }
770#JT:      }
771#RN:
772#JN:      // Determine if THT (any pad with drill) or SMD
773#MX:      const isTHT = comp.pads.some(p => p.drill_nm != null && p.drill_nm > 0);
774#QB:      const compHeight = isTHT ? THT_HEIGHT_MM : SMD_HEIGHT_MM;
775#VQ:
776#HN:      if (isTHT) thtCount++;
777#HY:      else smdCount++;
778#MT:
779#NQ:      // Material: IC (U/IC prefix) = dark gray, passive (R/C/L) = tan
780#RK:      const prefix = comp.refdes.replace(/[0-9]+$/, '').toUpperCase();
781#KV:      const isIC = prefix === 'U' || prefix === 'IC';
782#VN:      const mat = isIC ? icMat : passiveMat;
783#NR:
784#ZQ:      // Create box at component position
785#QS:      const geo = new THREE.BoxGeometry(bodyW, bodyH, compHeight);
786#XN:      const mesh = new THREE.Mesh(geo, mat);
787#KV:
788#XP:      // Position: component center, on top of board
789#KT:      const cx = comp.x_nm * NM_TO_MM;
790#JJ:      const cy = comp.y_nm * NM_TO_MM;
791#XN:      const cz = BOARD_THICKNESS_MM + compHeight / 2;
792#VB:
793#TQ:      mesh.position.set(cx, cy, cz);
794#TM:
795#YQ:      // Rotation around Z-axis
796#TS:      const radians = (comp.rotation_mdeg / 1000) * (Math.PI / 180);
797#SN:      mesh.rotation.z = radians;
798#PH:
799#HB:      mesh.name = `component-${comp.refdes}`;
800#BX:      topGroup.add(mesh);
801#KQ:
802#TR:      // Refdes label as sprite
803#PJ:      const label = this.createRefdesLabel(comp.refdes);
804#ZX:      label.position.set(cx, cy, BOARD_THICKNESS_MM + compHeight + 0.3);
805#KN:      // Scale sprite relative to body size for readability
806#HK:      const labelScale = Math.max(bodyW, bodyH) * 0.8;
807#QZ:      label.scale.set(labelScale, labelScale * 0.5, 1);
808#WT:      topGroup.add(label);
809#SH:    }
810#YB:
811#JM:    this._componentCount = smdCount + thtCount;
812#WR:
813#HQ:    console.log(`[3D] Built ${smdCount + thtCount} component bodies (${smdCount} SMD, ${thtCount} THT)`);
814#HN:  }
