816#XN:  /**
817#PT:   * Create a sprite with refdes text rendered on a canvas texture.
818#VT:   */
819#TX:  private createRefdesLabel(text: string): THREE.Sprite {
820#PV:    const canvas = document.createElement('canvas');
821#WB:    const size = 128;
822#TW:    canvas.width = size;
823#RH:    canvas.height = size / 2;
824#HQ:
825#WT:    const ctx = canvas.getContext('2d')!;
826#WS:    ctx.clearRect(0, 0, canvas.width, canvas.height);
827#RB:
828#PQ:    // White text with slight shadow for readability
829#XY:    ctx.font = 'bold 32px monospace';
830#HZ:    ctx.textAlign = 'center';
831#HZ:    ctx.textBaseline = 'middle';
832#RK:
833#QZ:    // Shadow for contrast
834#QX:    ctx.shadowColor = 'rgba(0,0,0,0.8)';
835#NQ:    ctx.shadowBlur = 4;
836#SK:    ctx.shadowOffsetX = 1;
837#MS:    ctx.shadowOffsetY = 1;
838#SQ:
839#TW:    ctx.fillStyle = '#ffffff';
840#HW:    ctx.fillText(text, canvas.width / 2, canvas.height / 2);
841#SM:
842#TZ:    const texture = new THREE.CanvasTexture(canvas);
843#YT:    texture.minFilter = THREE.LinearFilter;
844#KN:    texture.magFilter = THREE.LinearFilter;
845#RP:
846#BK:    const spriteMat = new THREE.SpriteMaterial({
847#NN:      map: texture,
848#HZ:      transparent: true,
849#YV:      depthTest: false,
850#NK:      sizeAttenuation: true,
851#VT:    });
852#RQ:
853#MS:    const sprite = new THREE.Sprite(spriteMat);
854#TX:    sprite.name = `label-${text}`;
855#PN:    return sprite;
856#JM:  }
