866#SJ:  private animate = (): void => {
867#RV:    if (!this.active) return;
868#YB:    this.animFrameId = requestAnimationFrame(this.animate);
869#PQ:
870#JV:    // FPS tracking
871#NT:    const now = performance.now();
872#VV:    this.frameCount++;
873#ZJ:    const elapsed = now - this.lastFrameTime;
874#BP:    if (elapsed >= 1000) {
875#RX:      this.currentFps = Math.round((this.frameCount * 1000) / elapsed);
876#MX:      this.frameCount = 0;
877#ZW:      this.lastFrameTime = now;
878#BX:      this.updateDebugSurface();
879#RY:
880#HW:      // Log FPS every 5 seconds
881#BZ:      this.fpsLogTimer++;
882#XK:      if (this.fpsLogTimer % 5 === 0) {
883#NZ:        console.log(`[3D] FPS: ${this.currentFps}`);
884#NH:      }
885#SX:    }
886#NJ:
887#WJ:    if (this.controls) {
888#MK:      this.controls.update();
889#MR:    }
890#QZ:
891#RN:    if (this.renderer && this.scene && this.camera) {
892#HP:      this.renderer.render(this.scene, this.camera);
893#HV:    }
