907#YM:  private clearBoardGroup(): void {
908#NQ:    if (!this.boardGroup) return;
909#JB:
910#RT:    // Dispose loaded GLTF model scene graphs (nested children with separate materials)
911#SW:    for (const [_refdes, model] of this.loadedModels) {
912#YY:      model.traverse((obj) => {
913#KW:        if (obj instanceof THREE.Mesh) {
914#WN:          obj.geometry?.dispose();
915#PZ:          if (obj.material) {
916#KJ:            if (Array.isArray(obj.material)) {
917#JT:              obj.material.forEach(m => {
918#NP:                if (m.map) m.map.dispose();
919#BP:                m.dispose();
920#YV:              });
921#YQ:            } else {
922#WN:              const mat = obj.material as THREE.MeshStandardMaterial;
923#BW:              if (mat.map) mat.map.dispose();
924#HV:              mat.dispose();
925#QN:            }
926#KX:          }
927#WS:        }
928#PM:      });
929#BR:    }
930#YY:    this.loadedModels.clear();
931#JQ:
932#BX:    this.boardGroup.traverse((obj) => {
933#BK:      if (obj instanceof THREE.InstancedMesh || obj instanceof THREE.Mesh) {
934#KB:        obj.geometry?.dispose();
935#RR:        if (obj.material) {
936#PB:          if (Array.isArray(obj.material)) {
937#JT:            obj.material.forEach(m => m.dispose());
938#TK:          } else {
939#YS:            (obj.material as THREE.Material).dispose();
940#PM:          }
941#SB:        }
942#BQ:      }
943#BQ:      if (obj instanceof THREE.Sprite) {
944#RR:        const spriteMat = obj.material as THREE.SpriteMaterial;
945#MK:        spriteMat.map?.dispose();
946#MX:        spriteMat.dispose();
947#ZQ:      }
948#ZX:    });
949#PV:
950#WV:    while (this.boardGroup.children.length > 0) {
951#PW:      this.boardGroup.remove(this.boardGroup.children[0]);
952#SV:    }
953#VQ:
954#QY:    // Reset geometry counts
955#BS:    this._componentCount = 0;
956#MZ:    this._traceSegmentCount = 0;
957#TH:    this._padCount = 0;
958#KQ:    this._viaCount = 0;
959#WT:  }
960#HR:
961#JT:  private getMeshCount(): number {
962#SN:    let count = 0;
963#WM:    if (this.scene) {
964#QB:      this.scene.traverse((obj) => {
965#KZ:        if (obj instanceof THREE.Mesh || obj instanceof THREE.InstancedMesh) count++;
966#YK:      });
967#MW:    }
968#QJ:    return count;
969#JX:  }
