978#TB:  private updateDebugSurface(): void {
979#PQ:    const self = this;
980#PK:
981#PQ:    (window as any).__renderer3d = {
982#RQ:      get isActive() { return self.active; },
983#RZ:      get meshCount() { return self.getMeshCount(); },
984#ZY:      get drawCalls() { return self.getDrawCallCount(); },
985#VY:      get fps() { return self.currentFps; },
986#PX:      get componentCount() { return self._componentCount; },
987#NP:      get traceSegmentCount() { return self._traceSegmentCount; },
988#QK:      get padCount() { return self._padCount; },
